static int readInteger(Scanner scanner, String pergunta, int minimum, int maximum) {
    while (true) {
        System.out.print(pergunta);
        String text = scanner.nextLine().strip();

        try {
            int value = Integer.parseInt(text);
            if (value >= minimum && value <= maximum) {
                return value;
            }
            System.out.printf("Use a value between %d and %d.%n", minimum, maximum);
        } catch (NumberFormatException error) {
            System.out.println("Digite a number entire, as 18.");
        }
    }
}

