public class BankAccount {
    private String accountHolder;
    private double balance;

    public BankAccount(String accountHolder, double balanceInitial) {
        this.accountHolder = accountHolder;
        this.balance = Math.max(balanceInitial, 0);
    }

    public double getBalance() { return balance; }

    public void deposit(double value) {
        if (value > 0) balance += value;
    }

    public boolean withdraw(double value) {
        if (value <= 0 || value > balance) return false;
        balance -= value;
        return true;
    }
}

// "facade" encapsulation -- doesn't solve anything:
public void setBalance(double balance) { this.balance = balance; } // still allows negative balance!

// truth encapsulation -- exposes operations, not the field:
public boolean withdraw(double value) { /* validate business rule */ }

public final class Point {
