}

public interface Notifier {
    void send(String message); // abstract -- each implementation defines

    // default: default implementation, subclasses can override or not
    default void sendUrgent(String message) {
        send("[Urgent] " + message);
    }

    // static: utilidade ligada to the contrato, call in the interface
    static String markUrgent(String message) {
        return "[Urgent] " + message;
    }
}

