public void transfer(Connection connection, long accountSource, long accountRecipient, double value) throws SQLException {
    connection.setAutoCommit(false); // the partir fromNow, nada and confirmado until commit() explicit
    try {
        try (PreparedStatement debit = connection.prepareStatement(
                "UPDATE accounts SET balance = balance - ? WHERE id = ?")) {
            debit.setDouble(1, value);
            debit.setLong(2, accountSource);
            debit.executeUpdate();
        }
        try (PreparedStatement credit = connection.prepareStatement(
                "UPDATE accounts SET balance = balance + ? WHERE id = ?")) {
            credit.setDouble(1, value);
            credit.setLong(2, accountRecipient);
            credit.executeUpdate();
        }
        connection.commit(); // only now the two mudancas ficam permanentes, JUNTAS
    } catch (SQLException e) {
        connection.rollback(); // desfaz the debit and the credit together -- nada stays confirmado by the half
        throw e;
    } finally {
        connection.setAutoCommit(true); // returns the connection to the state default Before of return to the pool
    }
}

Savepoint beforeOfCredit = connection.setSavepoint();
try {
    // tenta the credit...
} catch (SQLException e) {
    connection.rollback(beforeOfCredit); // desfaz only the that veio after of the savepoint, keeps the debit
}

