    if (order.valueSuspicious()) {
        throw new IntegrationFailure("value outside of the default"); // reverts processOrder entire...
    }
}

@Service
public class AuditService {
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void register(String event) {
        repositoryAudit.save(new RecordAudit(event));
        // ...but this record of audit already was committed in Its Own transaction
        // suspended/independently -- survives to the rollback of processOrder above.
    }
}

@Test
void shouldDetectConflictOfVersionInLoanConcurrent() throws Exception {
    Exemplar exemplar = repository.save(new Exemplar("book-1"));
    ExecutorService pool = Executors.newFixedThreadPool(2);
    CountDownLatch largada = new CountDownLatch(1);

    Callable<Boolean> tentarBorrow = () -> {
        largada.await(); // forces the two threads the iniciar juntas, in the same instant
        try {
            serviceLoan.borrow(exemplar.getId());
            return true;
        } catch (ObjectOptimisticLockingFailureException e) {
            return false; // the attempt that failure ends exactly here
        }
    };

    List<Future<Boolean>> results = pool.invokeAll(List.of(tentarBorrow, tentarBorrow));
    largada.countDown();

    long sucessos = results.stream().filter(f -> {
        try { return f.get(); } catch (Exception e) { return false; }
    }).count();

    assertThat(sucessos).isEqualTo(1L); // wins exactly a result, never the two nor no
}

