    public ProblemDetail handleItemUnavailable(ItemUnavailableException e) {
        ProblemDetail problema = ProblemDetail.forStatus(HttpStatus.CONFLICT); // 409
        problema.setTitle("item unavailable");
        problema.setDetail(e.getMessage());
        problema.setProperty("code", "item.unavailable");
        return problema;
