    @ExceptionHandler(MethodArgumentNotValidException.class) // triggered by @Valid when failure
    public ProblemDetail handleValidation(MethodArgumentNotValidException e) {
        ProblemDetail problema = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST); // 400
        problema.setTitle("Data invalid");
        problema.setProperty("code", "validation.field-invalid");
        problema.setProperty("errors", e.getBindingResult().getFieldErrors().stream()
            .map(error -> error.getField() + ": " + error.getDefaultMessage())
            .toList()); // streams, chapter 13
        return problema;
    }

    @ExceptionHandler(Exception.class) // safety net -- NEVER let stack trace leak
    public ProblemDetail handleErrorGeneric(Exception e) {
        ProblemDetail problema = ProblemDetail.forStatus(HttpStatus.INTERNAL_SERVER_ERROR); // 500
        problema.setTitle("internal error");
        problema.setDetail("Something deu wrong. Tente novamente.");
