@Service
public class JwtService {
    private final String keySecret = "..."; // NEVER really hardcoded -- comes from environment variable (chapter 27!)

    public String generateToken(Authentication autenticado) {
        String authorities = autenticado.getAuthorities().stream()
            .map(GrantedAuthority::getAuthority)
            .collect(Collectors.joining(","));
        return Jwts.builder()
            .subject(autenticado.getName())
            .claim("role", authorities)
            .issuedAt(new Date())
            .expiration(new Date(System.currentTimeMillis() + 3600_000)) // 1 hour
            .signWith(keyAsBytes())
            .compact();
    }
}

@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    return http
        .csrf(csrf -> csrf.disable()) // ver secao CSRF abaixo -- the razao certa, not "because and API"
        .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .authorizeHttpRequests(auth -> auth
            .requestMatchers("/auth/login", "/auth/register").permitAll()
            .requestMatchers(HttpMethod.GET, "/books/**").permitAll()
            .requestMatchers("/admin/**").hasRole("ADMIN")
            .anyRequest().authenticated()
        )
        .exceptionHandling(ex -> ex
            .authenticationEntryPoint((req, res, e) -> res.sendError(HttpStatus.UNAUTHORIZED.value()))
            .accessDeniedHandler((req, res, e) -> res.sendError(HttpStatus.FORBIDDEN.value()))
        )
        .oauth2ResourceServer(oauth -> oauth.jwt(jwt -> jwt
            .decoder(jwtDecoder())
            .jwtAuthenticationConverter(jwtAuthenticationConverter())
        ))
        .build();
}

@Bean
public JwtDecoder jwtDecoder() {
    // HMAC (key simetrica) only does sentido here because Is application
    // issues and validates its own token. When the issuer is external (next
    // of OIDC), the validation uses keys assimetricas publicadas via JWK Set --
    // the mecanismo of signature changes, but the encaixe in the filter chain, via
    // oauth2ResourceServer().jwt(...), and the same of the two sides.
    return NimbusJwtDecoder.withSecretKey(keyAsBytes()).build();
}

@Bean
public JwtAuthenticationConverter jwtAuthenticationConverter() {
    var authoritiesConverter = new JwtGrantedAuthoritiesConverter();
    authoritiesConverter.setAuthorityPrefix("ROLE_");
    authoritiesConverter.setAuthoritiesClaimName("role"); // same name of claim used in generateToken
    var converter = new JwtAuthenticationConverter();
    converter.setJwtGrantedAuthoritiesConverter(authoritiesConverter);
    return converter;
}

public class JwtAuthFilter extends OncePerRequestFilter {
    @Override
    protected void ofFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        String header = req.getHeader("Authorization");
        if (header != null && header.startsWith("Bearer ")) {
            String token = header.substring(7);
            if (jwtService.validate(token)) {
                // here you same montaria the Authentication and the colocaria
                // in the SecurityContextHolder -- precisely the step that
                // oauth2ResourceServer().jwt() already does by you
            }
        }
        chain.ofFilter(req, res);
    }
}
