@Service
public class OrderEventPublisher {
    private final KafkaTemplate<String, OrderCompletedEvent> kafkaTemplate;

    public OrderEventPublisher(KafkaTemplate<String, OrderCompletedEvent> kafkaTemplate) { // injection, chapter 22
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publishOrderCompleted(OrderCompletedEvent event) {
        // key = orderId -- ensures events of the SAME order always land on the SAME partition (order preserved, chapter 41)
        CompletableFuture<SendResult<String, OrderCompletedEvent>> future =
            kafkaTemplate.send("orders-completed", event.orderId(), event);

        future.whenComplete((result, error) -> {
            if (error != null) {
                // envio asynchronous -- error of rede/broker only aparece here, not in the call of send()
                log.error("Failure to the publish event of the order {}", event.orderId(), error);
            } else {
                log.info("Event published in the partition {} offset {}",
                    result.getRecordMetadata().partition(), result.getRecordMetadata().offset());
            }
        });
    }
}

