    private boolean ready = false; // WITHOUT volatile

    void markReady() { ready = true; }   // Thread A calls this
    void esperar() {
        while (!ready) { }                // Thread B gets stuck HERE FOREVER,
                                            // even after marking ready=true --
                                            // because B might be reading a value
                                            // old "curly", never updated
                                            // from main memory
    }
}

