class No {
    int value;
    No left, right;
    No(int value) { this.value = value; }
}

// search tree: left smaller, right larger.
// Search is O(log n) when height is logarithmic; no balancing,
// ordered insertions can form a list and degrade to O(n).
boolean find(No root, int alvo) {
    if (root == null) return false;              // base case of recursion
    if (root.value == alvo) return true;
    return alvo < root.value
        ? find(root.left, alvo)      // discard the entire right half
        : find(root.right, alvo);      // discard the entire left half
}

// simple representation: adjacency list
Map<String, List<String>> graph = new HashMap<>();
graph.put("A", List.of("B", "C"));
graph.put("B", List.of("D"));
graph.put("C", List.of("D"));
graph.put("D", List.of());

// breadth-first search (BFS) -- traverses "layer by layer", using a Queue:
void bfs(String start) {
    Queue<String> queue = new LinkedList<>();
    Set<String> visited = new HashSet<>();
    queue.offer(start);
    visited.add(start);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        System.out.println(current);
        for (String neighbor : graph.get(current)) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }
}

